// What went live and when, in plain English, newest first. Shown in the Owner area's "Change log" next to the Phases & Tasks change history.
// ADD AN ENTRY (at the top) every time something is put live. The exact technical record is the code history on GitHub; this is the readable version.

export interface ReleaseNote {
  /** when it went live, ISO with the UK offset */
  at: string
  title: string
  detail: string
}

export const RELEASE_NOTES: ReleaseNote[] = [
  { at: '2026-11-20T09:00:00+01:00', title: 'Take-off: Demolition calculator panel tidied', detail: 'When a Demolition line in Take-off is priced by one of its calculators (Wall Removal, Strip-Out by Room, Waste and Skips, Outbuildings and External), the Properties panel no longer shows a selling price of 0.00 pounds at the top or the empty Sub-Phase and Task pickers under the calculator card: the price shown is the calculator price on its card, and the Construction Type list is the one place to choose. The three calculators that take typed sizes (not Wall Removal) now say the drawn line is only a marker on the plan and show Marker on the card instead of a length of 0.00 m. Wall Removal still uses the length of the line you draw as the length of wall removed.' },
  { at: '2026-11-19T09:00:00+01:00', title: 'Take-off: scale presets fixed', detail: 'The scale drop-down in Take-off measured wrongly: its presets used a made-up size for a picture pixel, so for example 1:100 on A1 came out about 17 times too small. The presets now work out real distances from the paper size. A PDF page knows its own paper size, so an A1 PDF at 1:150 now measures correctly with one click. The scale list is now 1:20, 1:50, 1:75, 1:100, 1:125, 1:150, 1:200, 1:250 and 1:500 plus Custom. A new paper button beside it (for example A1) shows the paper size and lets you change it. A plan that is a plain image, such as a scan or photo, asks what paper it is the first time you pick a scale and remembers the answer, taking the picture as the whole sheet. For a cropped or scanned plan, Calibrate against a known length is still the most reliable way. Check a preset with the Measure tool on a wall of known length. Picking a preset changes the scale of the showing sheet only and remeasures its items, as before.' },
  { at: '2026-11-18T09:00:00+01:00', title: 'Take-off: saving to your account now works', detail: 'Fixed Take-off take-offs never reaching your account. Each take-off was given a short random reference, but your account only accepts proper long ones, so every save to the account was refused without saying so: My Take-offs stayed empty and Close take-off warned that the take-off could not be saved. New take-offs now get a proper reference, and a take-off already on your computer is given one the first time you open Take-off, with its plan pictures moved across, and is then saved to your account normally. If a save fails the message now says why. Plan pictures uploaded before this fix under the old reference are cleaned up automatically.' },
  { at: '2026-11-17T09:00:00+01:00', title: 'Take-off: Reset button renamed', detail: 'The full-reset button in Take-off, which wipes the drawings, items and plans but keeps the name, address and scale (after a confirmation, with a recovery copy), is now called Reset instead of Takeoff, so it is not confused with Close take-off, which saves the job and clears the screen. The Close take-off and My Take-offs buttons also moved next to the take-off name at the top left, so they are no longer cut off on narrower screens.' },
  { at: '2026-11-16T09:00:00+01:00', title: 'Take-off: Close take-off', detail: 'Take-off now has a Close take-off button, where + New used to be. Press it when you finish working on a job: the take-off is saved to your account under the name you gave it and the screen is cleared to a fresh, empty take-off with no name, address, customer or plans, which is what Take-off shows the next time you open it. To go back to a job, click My Take-offs and press Open on it, and its drawings, priced items and plans come back. A new take-off now shows Name this take-off at the top: click it and type the job name so it is easy to find in the list. If the save does not work it warns you before closing so nothing is lost. A take-off with nothing in it is no longer saved to your account, so blank ones do not pile up in My Take-offs (any already there can be deleted with the bin button). Leaving Take-off without pressing Close simply reopens the same take-off next time.' },
  { at: '2026-11-15T09:00:00+01:00', title: 'Take-off: plans are saved to your account', detail: 'The plan pictures in Take-off are now saved to your account as well as on the computer, so a take-off opens with its plans on any computer. When you add a plan (an image, or each page of a PDF) it is copied to your account in the background while you carry on drawing, and a small cloud mark on its sheet tab shows how it is getting on: a cloud with dots while it saves, a cloud with a tick when it is safe in your account, and a cloud with a warning if it did not save (press it to try again). Take-offs you already have are caught up the first time you open them on the computer that holds their plans. Open a take-off from My Take-offs on a different computer, or after clearing the browser, and each sheet fetches its plan from your account automatically: the Add Plan message now only appears if the picture is in neither place. Deleting a take-off from My Take-offs now removes its plan pictures from your account too. A plan over 10MB is squeezed a little to fit, and if it still will not fit it stays on that computer only and the sheet tab says so. The pictures use a private folder that only you can read, the same one your quote attachments use, and they count towards your storage (roughly 1 to 5MB for each plan).' },
  { at: '2026-11-14T09:00:00+01:00', title: 'Take-off: My Take-offs list', detail: 'Take-off now has a My Take-offs button, next to + New, that lists every take-off saved to your account, newest first, with its name, customer and address if set, when it last changed and its sheet names. Open puts that take-off back on screen with its drawings, priced items, sheets and scales, saving the one you were on first so nothing is lost. A name box lets you start a new take-off for a particular job, for example 14 Elm Road rear extension, and the bin button deletes a take-off with its sheets and plan pictures after a confirmation. Rename a take-off by clicking its name at the top of Take-off, as before. The + New button no longer throws the take-off away: it saves the current one to your account first, tells you it is saved and can be opened again from My Take-offs, and warns you before starting a new one if the save did not work. The customer, reference and site address of a take-off are now saved to your account as well as on the computer. The plan pictures themselves still stay on the computer where you loaded them: open a job on another computer and the sheets and drawings are there, and Add Plan puts the pictures back into the same sheets.' },
  { at: '2026-11-13T09:00:00+01:00', title: 'Take-off: Measure tool', detail: 'Take-off has a new Measure tool, a ruler button in the tool list under Polygon, available in every phase. Click the start, click along the route, and double-click to finish: each segment shows its length beside the line and the total runs on at the end. With three or more points it also shows the area and perimeter the shape would have if closed, handy for a quick room size. It measures at the scale of the sheet you are looking at and warns you if that sheet scale has not been set yet. It creates nothing in the schedule and nothing is priced or saved: the line stays on the plan until you press Esc, press Clear, change tool or change sheet. To price something you have measured, draw it with the Line or Polygon tool. Also fixed: the status bar at the bottom of Take-off now names the Click and Electrical tools properly instead of saying Polygon.' },
  { at: '2026-11-12T09:00:00+01:00', title: 'Take-off: several plans as sheets', detail: 'Take-off now works with several plans in one take-off. Each plan you load becomes a sheet with its own picture, its own scale and its own drawings, shown as tabs along the bottom of the plan (click to switch, double-click to rename, the cross removes a sheet, + Plan adds another). Load Plan is now Add Plan. A multi-page PDF asks which pages you want and makes a sheet of each. A new sheet shows an orange warning until you set its scale, and setting a scale only remeasures that sheet, never the others, so a floor plan at 1:50 and an elevation at 1:100 each measure correctly. Switching sheets shows only that sheet drawings and electrical points, while everything still feeds the same phases, calculators and one job-wide schedule and total. The schedule has a Show filter for one sheet or all of them, each item shows which sheet it came from, and clicking an item on another sheet takes you to that sheet. Send to Quote works as before and each item carries its sheet name as its Drawing Ref. The plan pictures are now kept in the browser own larger database on your device instead of the small local storage, where one big plan could stop the whole take-off from saving. Take-offs with one plan from before are moved into a sheet called Plan 1 the first time you open them. Plan pictures stay on the device they were loaded on: open the take-off on another computer and the sheets and drawings are there, a sheet that has no picture there says so, and Add Plan puts the picture back into that same sheet. Measure each thing from one plan only, because the same wall on two plans would be counted twice.' },
  { at: '2026-11-11T09:00:00+01:00', title: 'AI scope chat: plans are kept on the quote and can be used again', detail: 'Plans and photos you attach in the AI scope chat are now saved as the quote own attachments (as Plan / Drawing), so you can see them in the quote Attachments section after saving, and they carry across to the job when it is confirmed. This works from the AI Scope Workspace, the Quick Quote chat and the chat inside a saved quote. Before this, files attached in the chat were filed under a shared draft label and never linked to the quote. When you open a saved quote and press Edit with AI, a Files saved on this quote strip now shows at the top of the scope writer: View opens a file so you can check it yourself, and Show the AI adds it to your next message so the AI can read the plan again while it changes the scope. The buttons are clearer too: Update scope only changes the written scope and leaves every phase and price on the quote as they are, while Build Estimate replaces all the phases from the scope. Files attached in the chat before this change are not linked to any quote.' },
  { at: '2026-11-10T09:00:00+01:00', title: 'AI scope chat: Build Estimate no longer gets stuck', detail: 'Fixed the Build Estimate button in the AI scope chat staying grey after the AI had read your plans and written a scope. The button only turned on when the AI reply contained its scope between special tags, and a reply from plans could come back without them or be cut off before the end, leaving nothing to build from and no explanation. Now a scope that is cut off is still used (with a warning that the end may be missing), a reply with no tags can be used as the scope with a new button, Use the AI last reply as the scope, and the chat tells you when a reply ran out of room. The AI also has room for roughly twice as long a scope, and every AI reply is no longer counted twice behind the scenes.' },
  { at: '2026-11-09T09:00:00+01:00', title: 'AI quote now prices plastering, render and wall insulation', detail: 'The AI quote now fills in the three Plastering & Boarding calculators from the written scope, the way it already does for plumbing, drainage and demolition. It prices Internal Plastering & Boarding by room (the rooms the scope names, with what the walls and ceiling get), External Render by wall (walls with a stated length, the render type, windows and doors, and scaffold only if the scope asks for it) and Wall Insulation & Backing by wall (walls with a stated length, the lining and thickness, vapour control layer, metal lath and timber backing). It uses each calculator own rates, labour and settings, so the price matches what the calculator shows when you open it. It never invents a length, area or size: a wall with no stated length is left out and windows or doors not mentioned are not counted. Anything it had to assume, such as a typical room size, dot-and-dab walls and a board-and-skim ceiling when the scope does not say, the render system or the insulation thickness, is said in the review note on that line so you can check it. Vaulted ceilings stay on their own task lines. Open the calculator from the quote to change anything. All rates are samples to check against real jobs.' },
  { at: '2026-11-08T09:00:00+01:00', title: 'New calculator: Wall Insulation & Backing by wall', detail: 'Plastering & Boarding now has a Wall Insulation & Backing calculator that prices internal wall insulation wall by wall. Each wall has a length, height, windows and doors, and gets PIR insulated plasterboard fixed to the wall (25 to 70mm), PIR between timber battens with plasterboard over, or mineral wool between a stud lining with plasterboard over. A taped vapour control layer (ticked by default for the batten and stud linings, with a warning if it is switched off) and insulated reveals are optional, and expanded metal lath to steelwork or soffits and timber backing for heavy fixings are typed per wall, with a carpenter for the backing. It works out the boards, insulation, battens or studs, adhesive and sundries, the fixer hours, a labourer, and shows how much each lining takes off the width of the room. The skim over the board is still priced in the Internal Plastering & Boarding calculator, so nothing is counted twice, and it always warns to have the condensation risk assessed and the wall checked for damp first. In Take-off, a plaster line has the Priced by choice: pick Wall Insulation & Backing (by wall) and the length of the line you drew becomes the first wall length. A Back Office sub-phase for it is added automatically, listed after your existing plastering sub-phases. External wall insulation is not in it, and the AI quote does not use it, so plastering scopes keep using your task lines. All rates and hours are samples to check against real jobs.' },
  { at: '2026-11-07T09:00:00+01:00', title: 'New calculator: External Render by wall', detail: 'Plastering & Boarding now has an External Render calculator that prices rendering wall by wall. Each wall (one side of the building) has a length, height, windows, doors and any gable above the eaves, and the area is worked out with the openings taken out and the reveals put back. Each wall gets sand and cement render (scratch and float coats, with optional masonry paint), monocouche on a scratch coat, or thin-coat silicone on a mesh-reinforced base coat, onto new brick or block, existing render (cleaned and keyed) or painted masonry (bonding coat first). Beads are worked out from the corners, base and reveals unless you type them, movement joints are optional, a labourer is included, and a wall from scaffold or hard to reach adds time. Scaffold is only priced if you tick it, because it is usually priced once for the whole job under Site Setup. In Take-off, a plaster line has the Priced by choice: pick External Render (by wall) and the length of the line you drew becomes the first wall length, following the line if you change it. A Back Office sub-phase for it is added automatically, listed after your existing plastering sub-phases. External wall insulation under the render is not in it yet, and the AI quote does not use it, so plastering scopes keep using your task lines. All rates and hours are samples to check against real jobs.' },
  { at: '2026-11-06T09:00:00+01:00', title: 'New calculator: Internal Plastering & Boarding by room', detail: 'Plastering & Boarding now has a calculator that prices internal plastering room by room. Add the rooms (living room, kitchen, bedroom and so on) with their size, doors and windows, then say what each wall and ceiling gets: a skim over existing board or plaster (with or without a bonding coat), two-coat plaster to masonry, plasterboard dot-and-dabbed to masonry and skimmed, plasterboard fixed to studs or joists and skimmed, new board over an old ceiling, or board taped and jointed only. Beads (worked out from the windows unless you type them), coving and access hatches are optional per room. It works out the board, plaster bags, adhesive and sundries from the areas, the plasterer hours, a labourer to carry and mix, an extra for an occupied or hard-to-reach job, and an optional access tower. New rooms start with dot-and-dab walls and a board-and-skim ceiling, and you can change what the next room starts with. In Take-off, a plaster line has a new Priced by choice (or pick the sub-phase before you draw): choose Internal Plastering & Boarding (by room) and the line becomes a marker with an Open calculator button, with a way back to the old Finish Type pricing by wall length and height. A Back Office sub-phase for it is added automatically, listed after your existing plastering sub-phases. Vaulted ceilings are not in it (they stay on their own tasks), and the AI quote does not use it yet, so plastering scopes keep using your task lines. All rates and hours are samples to check against real jobs.' },
  { at: '2026-11-05T09:00:00+01:00', title: 'AI quote now prices drainage, services and demolition', detail: 'The AI quote now fills in the Drainage & Services and Demolition calculators from the written scope, the way it already did for plumbing. For drainage it prices Underground Drainage (runs with a length, trench depth, chambers, sewer connections, CCTV), Soakaway & Rainwater (sized from the roof and paved areas it states, with channel drains, gullies and water butts) and Services Connections (water, gas, electricity and telecoms). For demolition it prices Wall Removal / Knock-Through (one wall), Strip-Out by Room, Waste & Skips and Outbuildings & External. It uses each calculator own rates, labour and digger days, so the price matches what the calculator shows when you open it. It never invents a length, area or volume: a run, wall, waste item or building with no stated size is left out, and anything it had to assume (a trench depth, a typical room size, a wall taken as load-bearing solid brick) is said in the review note on that line so you can check it. Open the calculator from the quote to change anything. All rates are samples to check against real jobs.' },
  { at: '2026-11-04T09:00:00+01:00', title: 'Three new Demolition calculators', detail: 'Demolition now has three more calculators, listed after Wall Removal in the Take-off Construction Type list. Strip-Out by Room: add the rooms (kitchen, bathroom and so on) and each brings its usual items for its size, such as floor, ceiling and wall finishes, skirting, doors, fireplace, kitchen units, sanitaryware and radiators, each with its labour hours and waste, plus dust protection, plumber and electrician disconnection, an optional asbestos survey and the skips the waste fills. Waste and Skips: enter waste by kind (general, rubble, soil, plasterboard, timber, metal, green) and it gives the skips (heavy waste only part fills a skip), with an optional grab lorry, hazardous loads and road permits. Outbuildings and External: garages, sheds, hard surfaces, walls and fences, with the base broken out by mini excavator or by hand, rubble and general skips or a grab lorry, and an asbestos roof as a provisional sum. Sizes are typed into the calculator (a drawn line does not feed them), the entries sit after your existing demolition types so a new line still starts on a task, and a Back Office sub-phase for each is added automatically. The AI quote does not pick them yet. All rates and hours are samples to check against real jobs.' },
  { at: '2026-11-03T18:00:00+01:00', title: 'New calculator: Wall Removal / Knock-Through', detail: 'Demolition now has a Wall Removal / Knock-Through calculator. Give it the length of wall taken out, the height, the thickness and what it is (a stud partition, a block partition, a solid brick wall, or a cavity or thick wall) and it works out the volume, the rubble and the skips it fills, and the demolition labour. For a load-bearing wall (ticked by default for brick and cavity walls) it adds the temporary needles and props hired by the metre per week, an indicative steel beam sized from the span with its padstones, boxing in the steel, a structural engineer fee allowance and a Building Control provisional sum. Plaster make-good to the ends, ceiling line and new reveals, a floor patch, dust protection and moving or capping services found in the wall are optional lines. It always says the structural engineer designs the real beam, and warns about a missing engineer, an opening over 6m, and checking for services and asbestos. In Take-off, draw a demolition line and pick Wall Removal / Knock-Through (calculator) in the Construction Type list: the length of the line is the length of wall removed. The calculator entry sits after your existing demolition types, so a new demolition line still starts on a task, and a Back Office sub-phase for it is added automatically. The AI quote does not pick it yet, so demolition scopes keep using your task lines. All rates are samples to check against real prices.' },
  { at: '2026-11-03T14:00:00+01:00', title: 'Take-off: calculator sub-phases listed after the task ones', detail: 'In the Plumbing and Heating and Drainage and Services phases, the new calculator sub-phases (Plumbing Installation, Heating Plant, Underfloor Heating, Pipework Runs, Underground Drainage, Soakaway and Rainwater, Services Connections) now come after the existing task-based sub-phases for a company set up from scratch, so a new line drawn in Take-off starts on a task sub-phase such as Kitchen or Underground Drainage, and the calculators are still in the list to pick. This was checked by driving the real Take-off screen with test data: every calculator opens from a drawn line (or a drawn floor for the floor calculators), carries over the drawn area and perimeter for floors, and saves its price. Companies that already have their Back Office keep the order they have.' },
  { at: '2026-11-03T10:00:00+01:00', title: 'New calculator: Services Connections', detail: 'Drainage and Services now has a Services Connections calculator for new supplies, diversions and cap-offs of water, gas, electricity and telecoms or broadband. Add a service for each supply, pick the utility and the kind of work (a new connection, a diversion or move, or a cap-off). The utility companys own charge is a provisional sum with a sample figure for each (for example a new water connection is 1,800 pounds and a gas cap-off 280), which you type over with the real quote. For a new or diverted supply you give the length of trench from the street or meter to the building, how it is dug (machine or by hand) and what it crosses (soft ground, block paving, tarmac or concrete), and it works out the trench at the width and depth that utility uses, the duct or pipe laid in it (25mm blue water pipe, a gas duct, an electric cable duct or a telecoms duct), a sand bed and cover, warning tape, backfill, the surface put back, the meter box or chamber if ticked, the soil taken away, and the digger by the days it is on site with fuel and delivery. A cap-off has no trench and just takes the charge. Hand digging, laying, backfilling and reinstating are suggested labour. It reminds you that the utility sets positions, depths and sizes, that gas work needs a Gas Safe engineer, and that charges and waiting times vary a great deal. It is a new sub-phase beside your existing Services Cap-off and Diversions tasks, which are untouched. All rates are samples to check against real prices. In Take-off, pick the Services Connections (by service) sub-phase on a drainage line and the calculator opens from the summary card.' },
  { at: '2026-11-02T18:00:00+01:00', title: 'New calculator: Soakaway and Rainwater', detail: 'Drainage and Services now has a Soakaway and Rainwater calculator. Give it the roof area and the paved area that drain to the soakaway and how much rain it must hold (20mm to start): it counts all the roof, 80 percent of the paving, and works out the storage, or you can type the designers own storage volume. Choose how many soakaways and what they are built from (crates, a stone-filled pit or concrete rings) and it works out the size of the hole with working room, the crates, stone or rings (with a cover slab), the geotextile wrap, a silt chamber at each inlet, the soil taken away, and the digger priced by the days it is on site with fuel and delivery. Channel drains (light or heavy duty, with a concrete bed and haunching and end caps and outlets), yard or rainwater gullies, downpipe connections to the drain and water butts are counted alongside. Nothing is added until you add it. It warns that the real size comes from an infiltration test and the designer, that a soakaway must be at least 5m from a building, and when one soakaway is very large. The pipes from the downpipes to the soakaway are surface water runs in the Underground Drainage calculator. It is a new sub-phase beside your existing Rainwater and Surface Water tasks, which are untouched. All rates are samples to check against real prices. In Take-off, pick the Soakaway and Rainwater (by area) sub-phase on a drainage line and the calculator opens from the summary card.' },
  { at: '2026-11-02T14:00:00+01:00', title: 'New calculator: Underground Drainage (by run)', detail: 'Drainage and Services now has an Underground Drainage (by run) calculator. Add a run for each length of drain with its own use (foul, surface water or combined), pipe size (110, 160 or 225mm), length, average trench depth, how it is dug (machine or by hand) and what it crosses (soft ground, block paving, tarmac or concrete). It works out the trench, the uPVC pipe and fittings, the granular bed and surround, the backfill and the soil taken away (or all of it taken away with imported backfill), trench support for runs deeper than 1.2m, and putting the surface back. The digger is priced by the days it is on site with its fuel and delivery, as in the foundation calculators, and hand-digging, laying, backfilling and reinstating are suggested labour. For the whole job you count inspection chambers (shallow or deeper), manholes and rodding eyes, connections to an existing drain, connections to the public sewer (a provisional sum, with a reminder that the water companys approval and charges are separate) and an optional CCTV survey. It warns about trenches deeper than 1.5m and drains with very little cover, and reminds you that falls, sizes and depths are the drainage designers. The quote wording follows the runs and the materials list can be printed or sent for prices. It is a new sub-phase beside your existing Drainage and Services ones, which are untouched. All rates are samples to check against real prices. In Take-off, Drainage and Services now works like Decoration and Plumbing: pick the Underground Drainage (by run) sub-phase on a line and the calculator opens from the summary card (the lengths are typed in the calculator).' },
  { at: '2026-11-02T10:00:00+01:00', title: 'AI quote now prices the plumbing calculators', detail: 'When you write a scope with plumbing in it, the AI quote now fills in the plumbing calculators from what you wrote, instead of leaving them empty. Plumbing Installation (by room) gets the rooms and fittings named (a bathroom, en-suite, kitchen and so on, with any freestanding bath, wet room or boiling tap, whole-house items, and the job situation such as an occupied house). A room with no fittings stated gets the usual fittings for that kind of room, and the review note says so. Sanitaryware, taps and radiators are left to the client unless the scope says you supply them. Heating Plant gets a gas combi boiler: the size, replace or new position, flue, controls and number of radiators. If the size is not stated it uses 28kW and says so. Underfloor Heating gets a zone for each room with an area stated in the scope (it never invents an area), with the pipe spacing, how it is laid and the distance to the manifold if given. Pipework Runs gets a run for each pipe length the scope states, with its size, material, routing and lagging. Each line is priced with the calculators standard rates and 20% profit, marked as needing review with a note on what was priced and assumed, and opening the calculator from the quote shows the same rooms, zones or runs. Nothing is invented: what the scope does not state is left out or said in the note. The four plumbing sub-phases also have hints so the AI knows when to choose them, and the older Boiler and Heating System sub-phase is now described as for system boilers, cylinders and heat pumps.' },
  { at: '2026-11-01T20:00:00+01:00', title: 'New calculator: Pipework Runs', detail: 'Plumbing and Heating now has a Pipework Runs calculator that prices pipe by the run, for the lengths a fittings all-in price in the Plumbing Installation calculator does not cover: long hot and cold runs, heating circuits, gas, waste and soil. Add a run, pick the kind of pipe (cold water, hot water, heating flow and return as a pair, gas, waste or soil), its size and material (copper or plastic, only the combinations that exist), the length in metres and how it is routed. The price is your plumbers all-in rate per metre (pipe, fittings, clips and fixing), with extra for chasing into a wall (+25%), burying in a screed (+30%) or working outside (+15%), and the job situation percentage added on top. Cold, hot and heating runs can be lagged. Extras are isolation valves, boxing in the pipework and a pressure test. It warns about gas pipework needing a Gas Safe engineer, a long run of 15mm hot water, long runs of small waste pipe and a missing pressure test. Use it alongside the room fittings, not instead of them, so short runs are not counted twice. The quote wording follows the runs and the materials list can be printed or sent for prices. It is a new sub-phase in Plumbing and Heating. All rates are samples to check against your plumber. In Take-off, pick the Pipework Runs sub-phase on a plumbing line and the calculator opens from the summary card (the lengths are typed in the calculator).' },
  { at: '2026-11-01T18:00:00+01:00', title: 'New calculator: Underfloor Heating (warm water)', detail: 'Plumbing and Heating now has an Underfloor Heating calculator for warm water underfloor heating, priced zone by zone. Add a zone for each room (or part of a room) that has its own thermostat and give it an area, how the pipe is laid (clipped to insulation in a screed, in low-profile overlay panels on an existing floor, or between joists on spreader plates), the pipe spacing (100, 150, 200 or 300mm) and how far it is from the manifold. It works out the pipe with the flow and return to the manifold, splits it into loops kept to about 100m, and prices the floor fixing material, the installer laying the pipe, the manifold (sized from the loops, up to 12 ports each), an actuator for each loop, a thermostat for each zone, a wiring centre, an optional mixing group (blending valve and pump), fitting the manifold, and the pressure test, balance and first heat-up. Each zone shows its pipe length, loops and a rough output, and it warns when a zone is too far from its manifold or the pipe is spaced too widely. The floor insulation, edge strip and the screed over the pipes are not in it: price them with the Screeded Floor calculator (a liquid screed is the usual one over underfloor heating). The heat source is the Heating Plant calculator, and electric heating mats stay under Electrics. It is a new sub-phase in Plumbing and Heating, and your Screed with Underfloor Heating sub-phase under Floors and Screeds is untouched. All rates are samples to check against real prices. In Take-off, pick the Underfloor Heating sub-phase on a plumbing line and the calculator opens from the summary card.' },
  { at: '2026-11-01T14:00:00+01:00', title: 'New calculator: Heating Plant (gas combi boiler)', detail: 'Plumbing and Heating now has a Heating Plant (by system) calculator for a gas combi boiler, priced itemised so each part is its own line you can change. Choose the boiler size (24, 28, 30 or 35kW, with what each suits), and whether it replaces the existing boiler where it is or goes in a new position. The Gas Safe engineers fitting is one price. Then the flue (horizontal through a wall, vertical through the roof, or the existing flue reused, with optional core drilling and a plume kit), the controls (none, a programmable thermostat or a smart thermostat), a magnetic system filter, a chemical clean of the system (a charge for each radiator), removing the old boiler, commissioning with the benchmark certificate, and metres of gas, flow and return and condensate pipework that move with the boiler, with an optional condensate pump. It warns about the Gas Safe requirement and about a boiler in a new position needing gas pipework and its own flue. Radiators and towel rails stay in the Plumbing Installation rooms, and the electrical connection, a cylinder and heat pumps are not in it (system boilers with a cylinder and heat pumps can be added later). It is a new sub-phase in Plumbing and Heating, so your existing Boiler and Heating System sub-phase and its tasks are untouched. All rates are samples to check against real prices. In Take-off, pick the Heating Plant (by system) sub-phase on a plumbing line and the calculator opens from the summary card.' },
  { at: '2026-11-01T10:00:00+01:00', title: 'New calculator: Plumbing Installation (by room)', detail: 'Plumbing and Heating now has a Plumbing Installation (by room) calculator, built like the Electrics one. Add a room (bathroom, en-suite, kitchen, utility, cloakroom, or a heated room) and it comes with its usual fittings: bath, shower, basin, WC, sinks, appliance connections, radiators and towel rails. Each fitting is priced at your plumbers all-in rate (the pipework to it and fixing it). A situation percentage (new build, refurbishment, occupied house, hard to reach, listed building) is added to the fittings, for the whole job or one room. Special fittings such as a freestanding bath, a wet room or a boiling water tap are an extra install charge on top, with the client or you supplying the item. A room can be priced by plumber days instead. Each room says whether the client or you supply the sanitaryware, taps and radiators: if you do, a PC sum is added for each. Whole house items are a pressure test and commissioning (in the starting price), stop tap, new main, manifold and booster pump. The quote wording follows the rooms, and the materials list can be printed or sent for prices. The boiler, cylinder or heat pump is not in it (a heating calculator is still to come). All rates are samples to check against your plumber. In Take-off, pick the Plumbing Installation (by room) sub-phase on a plumbing line and the calculator opens from the summary card. It adds a new sub-phase to the Plumbing and Heating phase in Back Office.' },
  { at: '2026-10-31T20:00:00+01:00', title: 'New calculator: Insulated Concrete Floor', detail: 'Floors and Screeds now has an Insulated Concrete Floor calculator. It is the Concrete Slab Floor calculator with its own saved settings, starting with 150mm of insulation under a 100mm slab, and the quote wording says insulated concrete floor and high-performance PIR. It prices the hardcore, sand blinding, membrane, insulation, mesh, edge strip and ready-mixed concrete from the floor area and perimeter you draw in Take-off, with optional digging out, a pump or wheelbarrows for the concrete, and a power float. The insulation list now goes up to 175mm and 200mm for enhanced insulation, in this calculator and in the Concrete Slab Floor. If you choose no insulation it warns you. All rates are samples to check against real prices. In Take-off, pick the Insulated Concrete Floor Build-Up Type on a drawn floor.' },
  { at: '2026-10-31T18:00:00+01:00', title: 'New calculator: Suspended Timber Floor', detail: 'Floors and Screeds now has a Suspended Timber Floor calculator, one calculator for a ground floor, an upper (first) floor and a loft floor (a loft room, or a lighter storage-only floor). Pick which floor at the top and it starts from sensible settings for that floor. From the floor area and perimeter you draw in Take-off it prices the joists (47mm wide, C16 or C24, at 400, 450 or 600mm centres, with extra doubled or trimming joists if you add them), the wall plates or joist hangers, strutting on longer spans, mineral wool insulation between the joists with netting, a vapour control layer and the decking (chipboard or plywood). The joist span follows the shorter side of the drawn floor until you type over it, and each joist size is checked against the span at floor loads, saying when it is too small and what would work. A ground floor also works out how many rows of sleeper wall the span needs and how long they are (priced separately under External Walls with the sleeper wall calculator, along with the vents), has wall plates on a DPC, and has an optional gravel or concrete ground cover. The ceiling under an upper or loft floor, and any steel beams, are not in the price. Labour is suggested for the carpenter and labourer, the quote wording follows the inputs, and the materials list can be printed or sent for prices. All rates are samples to check against real prices. In Take-off, pick the Suspended Timber Floor Build-Up Type on a drawn floor.' },
  { at: '2026-10-31T14:00:00+01:00', title: 'New calculator: Block and Beam Floor', detail: 'Floors and Screeds now has a Block and Beam Floor calculator. From the floor area and perimeter you draw in Take-off it works out the beams (at 440, 520 or 600mm centres, each as long as the span plus its bearing, with extra beams under walls if you add them), the infill blocks and grout, DPC under the beam ends, insulation over the blocks, a membrane and edge strip, and a lorry crane for lifting the beams in. The beam span follows the shorter side of the drawn floor until you type over it. Hardcore and blinding under the void are included by default and can be set to none, and digging out is optional (digger days, fuel, delivery and soil taken away, as in the foundations). Labour is suggested for the bricklayer and labourer, the quote wording follows the inputs, and the materials list can be printed or sent for prices. The walls and sleeper walls the beams sit on, and the screed on top, are priced separately. The beam supplier designs the beams for your spans and loads, and the calculator warns on long spans. All rates are samples to check against real prices. In Take-off, pick the Block and Beam Floor Build-Up Type on a drawn floor.' },
  { at: '2026-10-31T10:00:00+01:00', title: 'New calculator: Concrete Slab Floor', detail: 'Floors and Screeds now has a Concrete Slab Floor calculator. From the floor area and perimeter you draw in Take-off it prices the hardcore (with compaction allowance and plate hire), sand blinding, damp-proof membrane, insulation under the slab, reinforcing mesh with spacers, edge insulation strip and the ready-mixed concrete (C20, C25 or C30). Digging out is optional and starts at none: add a dig depth and it prices the digger days on site, fuel, delivery and the soil carted away. Getting the concrete in works as it does for foundations: lorry direct, a concrete pump, or extra men with wheelbarrows. A power float hire is a tick box. Labour is suggested and can be edited, the quote wording follows the inputs, and the materials list can be printed or sent for prices. A screed on top is priced with the Screeded Floor calculator. All rates are samples to check against real prices. In Take-off, pick the Concrete Slab Floor Build-Up Type on a drawn floor.' },
  { at: '2026-10-30T10:00:00+01:00', title: 'New calculator: Existing Floor Overlay', detail: 'Floors and Screeds now has an Existing Floor Overlay calculator. Choose self-levelling compound (the bags are worked out from the area and the depth, with primer and edge foam strip, both optional) or a plywood overlay over an old timber floor (sheets and fixings). It is all your own materials and labour, with a labourer or carpenter suggested for laying it, and warnings for a layer too thin to flow, one thick enough to need aggregate, or a floor that rises enough to affect the doors. The quote gets a short line and a full what is included text. In Take-off, draw the floor area and choose the Build-Up Type Existing Floor Overlay and the calculator opens sized from the drawing. All rates are samples to check.' },
  { at: '2026-10-29T10:00:00+01:00', title: 'Pitched roofs: a vaulted ceiling, and joining an existing roof', detail: 'The gable, hip and mono-pitch roof structure calculators have two additions. A Ceiling section lets you choose a flat ceiling (as before) or a vaulted one: a vaulted ceiling has no ceiling joists and a ridge beam (LVL or steel) with its bearings in place of the ridge board. The insulation and plasterboard lining of a vaulted ceiling are NOT priced in the roof: three new Vaulted ceiling tasks (insulation, plasterboard, skim) are in Plastering and Boarding under Ceiling Plastering and Boarding, the quote shows a yellow reminder while a roof is vaulted and none of them is on the quote, and the AI quote writer adds them when the scope has a vaulted ceiling. An end of a gable or hip roof, or the high edge of a lean-to, can now meet an existing roof instead of a wall: goes up onto an existing roof (abuts its slope), joins into an existing roof with valleys (gable and hip ends), or is built over part of an existing roof. The structure prices the bearer, ties, valley rafters, trimmers and opening up the existing roof, and the pitched roof covering calculator, which has the same choices, prices the lead flashing along the join, lead-lined valleys and the existing tiling made good. All rates are samples to check.' },
  { at: '2026-10-28T10:00:00+01:00', title: 'New calculator: Screeded Floor', detail: 'Floors and Screeds now has its first calculator, the Screeded Floor. It prices the screed the way you buy it: the screeding firm is a subcontract rate per m2 worked out from the thickness and the amount of screed (a laying charge plus a charge per cubic metre), with their materials, pump and machinery included, and a minimum charge that tops a small floor up. Your own part is priced separately: insulation board, a damp-proof or separating membrane, edge strip and mesh (all optional, edge strip on by default), with a labourer suggested for fitting them. Choose sand:cement or liquid screed and the thickness; a thin screed over insulation gets a warning. The quote gets a short line and a full what is included text that follow your choices. In Take-off, draw the floor area and choose the Build-Up Type Screeded Floor: the calculator opens sized from the area and perimeter drawn. All rates are samples to check against your firm, and each can be edited in the breakdown. Screed with Underfloor Heating, Existing Floor Overlay and the structural floors are still to come.' },
  { at: '2026-10-27T10:00:00+01:00', title: 'AI scope writer: thinking dots, and a Building button', detail: 'When you send an answer to the AI scope writer, three green dots now bounce with the words Thinking in the chat until it replies (before there was a still row of dots that was easy to miss). While the estimate is being built, both Build Estimate buttons, the one in the scope draft box and the one in the bar under the chat, change to Building and cannot be pressed a second time.' },
  { at: '2026-10-26T10:00:00+01:00', title: 'Quotes: Recently deleted, and saving that tells you when it did not save', detail: 'Deleting a quote no longer destroys it. It moves to Recently deleted at the bottom of the Saved quotes page (under Archived Quotes), with its versions, and can be brought back with Restore; only Delete for good removes it for ever. A deleted quote is hidden everywhere, including from the client portal. Saving a quote now checks the answer from the database: if it did not save (an error, or the quote no longer exists, for example deleted in another window) you are told plainly and what is on screen is kept, with the choice to save it as a new quote. The automatic background save shows a red Not saved beside the Editing line if it fails, instead of failing silently. Changes made from the Saved quotes list (status, archive, marked as sent) say so too if they do not save. No database change is needed.' },
  { at: '2026-10-25T10:00:00+01:00', title: 'Foundation calculators: the digger priced by days on site, with fuel and delivery', detail: 'The Strip foundation, Trench fill, Pad, Raft and Piled foundation calculators now price the digger the way it is hired. A new section, Digger on site, shows how long the digging takes and lets you set the days the digger is on site (by default whole days, at least one, so half a day of digging is charged as a day; type a number if it will be there longer or shorter). Fuel is added for the days it is digging, and delivery and collection is added once, there and back. Each is its own line in the cost breakdown, so you can change the rate or untick it. The rates are samples (digger £260 a day with operator, fuel £25 a day, delivery and collection £120) to check against real hire prices. Small digging jobs will now price higher than before; quotes already saved are not changed.' },
  { at: '2026-10-24T10:00:00+01:00', title: 'Foundation calculators: getting the concrete in by pump or wheelbarrow', detail: 'The Strip foundation, Trench fill foundation and Pad foundations calculators have a new section, Getting the concrete in, for when the concrete lorry cannot reach the foundation. Choose a concrete pump (one pump visit with its operator plus a charge for each cubic metre pumped, added as plant) or extra men with wheelbarrows (say how many men and how far it is from the lorry; the man-hours are worked out and added as a labour line, with the wheelbarrow hire as plant). Nothing is added when the lorry can reach, as before. The quote description says the concrete is pumped or barrowed in. All the rates are samples to check, and each can be edited in the cost breakdown. The Raft foundation keeps its existing Pump the concrete tick.' },
  { at: '2026-10-23T10:00:00+01:00', title: 'Number boxes: you can now delete a number all the way and retype it', detail: 'In a number box, deleting the last digit used to put 0 (or the boxs minimum, often 1) straight back, so the first character never deleted and a new amount could not be typed over it. It happened in the calculators (width, depth and the like) and in most other number boxes across the app. Every number box now uses one shared box that lets you clear it and type a new amount, still works out prices as you type, and shows the real value when you click out of it.' },
  { at: '2026-10-22T10:00:00+01:00', title: 'Jobs: the Price requests button is renamed', detail: 'The button next to Add job on the Jobs page, and the window it opens, is now called Price requests (no job), so it is clear what it is for: price requests made from a calculators materials list before there is a job, and supplier quotes emailed in that the app could not place. Nothing else about it has changed.' },
  { at: '2026-10-21T14:00:00+01:00', title: 'Contacts: a Postcode box, and the full postcode on price requests', detail: 'Adding or editing a client, supplier or subcontractor in Contacts now has a Postcode box under Address, kept on its own so it can be used later (finding the nearest supplier, for example), and it shows in their details. It needs supabase/client-postcode.sql run on the database; until then what is typed in the box is not saved. A supplier asked for a price now sees the town and the full postcode (Tooting, SW17 0AB) instead of only the first half, because a skip or hire firm needs it to price the delivery. The house number and street are still hidden until you approve a price. A jobs address with no postcode written in it still shows only the town.' },
  { at: '2026-10-21T10:00:00+01:00', title: 'Orders: one New order button that asks suppliers for a price', detail: 'A jobs Orders window now has a single button, New order. Pick the kind of order and who to ask, and each supplier is sent the request and replies with their price and whether they can do it. Each kind has its own questions: a skip (what is going in, how long for), plant hire (with or without a driver, who delivers and collects, how long for), a portaloo (servicing, how long for), a new Waste removal or grab lorry (which service, what it is, how much), something else, and materials (still add from your products). For anything but materials the email and WhatsApp ask for a price and whether they can do it on your date, and a PDF quote to your quotes address is still welcome. Each supplier row has Enter their price, to type in what they told you by phone, WhatsApp or email (can they do it, price, date, what they said), and it is then compared and approved like any other reply. Already have a price? Use the link I already have a price: skip the quote to go straight to an order, as before. Materials orders made that way can also be built from your products list.' },
  { at: '2026-10-20T14:00:00+01:00', title: 'Price requests: a list to quote from, no price form', detail: 'A supplier asked for a price now receives a plain list of what you need (the items, the area, the delivery date, your purchase order number and your account number) and quotes from their own system. The request says exactly how to reply: email the quote as a PDF attached to the email to your companys quotes address, with your purchase order number on the quote and in the email subject, because a quote pasted into the email or sent as a link cannot be read. There is no Give your price button or link in the email, the WhatsApp message or the copied message, and an amended request asks for an updated quote. The Orders window now says Email the request and WhatsApp the request instead of link. The price form is not removed: it is switched off by one setting in the code (lib/supplier-quote-config.ts), older links still work, and it is used automatically for any company with no quotes email address set. The Please price each item line no longer says on the link. No SQL needed.' },
  { at: '2026-10-20T10:00:00+01:00', title: 'Order confirmations: a plain yes, please go ahead', detail: 'The email, WhatsApp message and copied text you send a supplier when you approve their quote and send the order now read as a simple go-ahead: Thank you for your quote (their reference). Yes, we would like you to go ahead with this order. Then our order reference, their quote reference, our account number, what it is (the items as a plain list), the delivery address, the delivery date and, at the end, a request to reply to confirm they will deliver on that date and quote the order reference on their invoice. The agreed price is kept as a small line. An order that did not follow a quote starts We would like to place the following order with you, and with no delivery date it asks them when they can deliver. The email has the title Please go ahead with this order and the subject Please go ahead: order PO-0007. Also fixed: an order made from an item-priced request no longer carries the line Please price each item below, and a single item in a list is shown as a list line, not in brackets. No SQL needed.' },
  { at: '2026-10-19T14:00:00+01:00', title: 'Subcontractors: Direct Labour who invoice can now be billed, and a Cash button for everyone', detail: 'The Direct Labour setting did two things at once: it put a workers timesheet costs in the Labour category, and it also treated them as paid through payroll, so they never got a bill and were never sent to Xero. They are now two settings. In Contacts, for a subcontractor, Direct Labour (costs go in Labour) has a separate box, Paid through PAYE payroll (no bill, not sent to Xero), which shows once Direct Labour is ticked. A full-time worker on CIS who invoices you is Direct Labour with the payroll box unticked: their week gets the Bills button, becomes a bill with the CIS deduction, and can be sent to Xero, while their costs still count as Labour. Anyone already marked Direct Labour is treated as on payroll until you change them, so nothing moves by surprise. Everyone who is not on payroll now also has a Cash button on the week and on each pending day, to record that they were paid in cash on the job, never as a bill and never sent to Xero (payroll people keep All cash and All PAYE). Needs supabase/sub-payroll.sql run once on each database; until then the new box cannot be saved and everything works as before.' },
  { at: '2026-10-19T10:00:00+01:00', title: 'Job costs: expected costs not invoiced yet, and the budget left', detail: 'Add cost manually in a jobs Costs window now has two choices at the top: a real invoice or receipt (as before) or an expected cost (not invoiced yet), such as monthly hire or a fee you know is coming. An expected cost takes what it is for, the cost type, the amount ex VAT, when the first invoice is expected and, optionally, repeat monthly for a number of months, which makes one entry per month. They never count as real costs: they show in the Still to come box, the Expected column of Quoted vs Actual and the margin including expected costs, and each has an Invoice arrived link that opens the Orders window, where pressing Invoice arrived turns that month into the real cost. Under the Quoted vs Actual table there are now two lines: Budget left so far (quoted cost minus real costs) and Budget left at end of job (after the expected costs still to come). The Financial Summary margin lines are renamed Margin so far (real) and Margin at end of job (including expected costs). The clients Outstanding balance is unchanged. Each expected month is kept as a placed order on account marked Expected cost, so it has a PO number and the email, WhatsApp and delivery buttons are hidden for it. No SQL needed.' },
  { at: '2026-10-18T20:00:00+01:00', title: 'Portal invite and quote emails now mention Selections', detail: 'The list of what the client portal is for, used in the portal invite email, the quote emails that explain the portal and the WhatsApp message, now includes Selections: add your ideas and web links for the things you want, such as skirting, light fittings, taps and tiles, with photos, so we know what to order and fit. The welcome box at the top of the clients portal, and your preview of it, lists Selections too (only for a client who can see that tab). No SQL needed.' },
  { at: '2026-10-18T18:00:00+01:00', title: 'Selections: a client ideas board on the portal', detail: 'The client portal has a new Selections tab where a client adds the things they have chosen for their home (skirting, light fittings, taps, tiles): what it is, the room, a photo from their phone camera or a PDF, a link, the product code and notes, who is buying it and when it is needed by. They can change an item, say I have decided, or delete it until you mark it Ordered, and they see your reply and the status. On the Jobs page each job has a Selections button (with a green count of new items) that opens a window with the items grouped by room, the photos, a status you set (Idea, Chosen, Checked by us, Ordered, Delivered, Installed) and a reply box. You get a phone alert when a client adds or changes an item (switch it on or off in Settings, Notifications) and a line on the dashboard. The builders preview of the portal shows the tab too. In a clients settings in Contacts there is a Selections tab box to switch it off for that client. Photos are made smaller before they are sent. A client cannot see or change anyone elses items, or an item after it is ordered. Needs supabase/job-selections.sql run once on each database; until then the tab tells the client it is not switched on yet. Clients are not emailed when you reply yet (they see it when they open the portal).' },
  { at: '2026-10-18T15:00:00+01:00', title: 'Emailed quotes: automatic reply asking for a PDF attachment', detail: 'When a supplier emails a quote to your quotes address and nothing the app can read is attached (no file, the quote pasted into the writing of the email, a Word file, or a file that is too big), they now get an automatic reply from your company asking them to send it again as a PDF attached to the email with the PO number on it, with a copy to you. It only replies to mail sent to the quotes address (never the documents one), only from a person (never a no-reply address, bounce, mailing list or auto-responder, and the reply is itself marked automatic), only to a supplier you actually asked (the email names one of your open PO numbers, or comes from the exact address on a price request; a cancelled or deleted request does not count), and at most once a day to the same address. The Emails received line says when a reply was sent. The price request email, the request WhatsApp and copied message and the supplier price page now also say the quote must be attached as a PDF, not pasted in or sent as a link. No SQL needed.' },
  { at: '2026-10-18T12:00:00+01:00', title: 'Emailed quotes: small pasted pictures are read too', detail: 'A quote pasted into the body of an email as a small screenshot (under about 30 KB) was still skipped, because pictures inside an email that small were all treated as signature logos. Now, when nothing else came with the email, the larger of the smaller pictures inside it (from about 5 KB, at most the two largest) are also checked as a possible quote. If a real PDF or photo is attached, small pictures inside the email are still ignored, and a picture inside the email is only ever checked as a quote: if it is not one it is left alone and not filed in the Documents inbox. No SQL needed.' },
  { at: '2026-10-18T10:00:00+01:00', title: 'Emailed quotes: a picture pasted into the email is now read', detail: 'A supplier whose system put the quote into the body of the email as a picture (rather than attaching a file) had it thrown away, because every picture the email itself points at was treated as a signature logo, and Emails received said there was no PDF or photo. A picture inside an email that is bigger than about 30 KB is now checked as a possible quote and read like an attached one; small ones (logos, icons) are still ignored. A picture inside the email is only ever checked as a quote: if it is not one it is left alone and not filed in the Documents inbox. The Emails received line now says what came with the email and why it was not used, for example a Word file, a file that was too big, or a logo that was too small to be a quote. No SQL needed.' },
  { at: '2026-10-17T19:00:00+01:00', title: 'Contacts: A to Z strip to jump through a long list', detail: 'A long Contacts list now has a slim A to Z strip down its right-hand side. Press a letter to jump to the first contact starting with it, or press and slide along the strip to run through the list quickly, as in a phone contacts list. It shows only the letters you have, appears once the list has more than 12 contacts, stays in view as you scroll, and follows the type filter (All, Clients, Suppliers, Subcontractors) and the search box. On a phone or tablet the jump leaves room for the bar across the top. No SQL needed.' },
  { at: '2026-10-17T17:00:00+01:00', title: 'Our account number with a supplier, on price requests and orders', detail: 'Editing a supplier or subcontractor in Contacts now has a box, Our account number with them, and the number shows in their details. It is put on what they are sent so they know which account it is for: a line, Our account, in the price request email, in the request WhatsApp and copied message, on the page the supplier opens to give their price, and in the order email and order WhatsApp message. It is looked up when the message is sent, so it always matches Contacts, by the contact the request was made from or, for a supplier typed in by hand, by an exact name when only one supplier has it. A supplier with no account number simply has no line. The WhatsApp and copied message for an amended price request now use the amended wording too (before, only the email did). No SQL needed.' },
  { at: '2026-10-17T14:00:00+01:00', title: 'Suppliers edited in Contacts now show in orders straight away', detail: 'A supplier or subcontractor is kept in two lists in the app, one for Contacts and one for orders, price requests and the Suppliers page, and both were only filled when the app loaded. Editing a supplier in Contacts therefore left the orders dropdown showing the old details until the page was reloaded. The two lists now change together, in both directions: editing, adding or deleting a supplier in Contacts or on the Suppliers page shows in the other at once, and a contact changed so that it is no longer a supplier or subcontractor drops out of the orders dropdown. Orders and requests already made keep the supplier details they were saved with. No SQL needed.' },
  { at: '2026-10-17T10:00:00+01:00', title: 'Price requests: amended requests, and the supplier quote reference', detail: 'When you edit a price request that suppliers already have and really change something (the wording, items, dates, area or how it is priced), it is marked as amended. Each supplier then shows an amber note (their price is for the earlier version, or the request was changed after you sent it) and the button becomes Email the amended request. The amended email and WhatsApp message say the request has changed and ask them to check it and update their price, and quote their earlier reference. Their price page shows an amended box until they reply again, and approving a price given before the change asks you to confirm. Suppliers can also type their own quote reference on their price page, and the app picks up the quote number printed on a quote they email in. It shows on their row (you can type or change it there), goes onto the order made when you approve them, and is quoted back to them in the order email and WhatsApp message. Needs supabase/job-orders-amend.sql run once on each database; until then everything works as before but the amended mark and the references are not kept.' },
  { at: '2026-10-16T21:00:00+01:00', title: 'Price requests and orders: Recently deleted', detail: 'Deleting a price request or an order no longer destroys it. It moves to Recently deleted, a button at the bottom of the Price requests window and of each jobs Orders window, with its suppliers and their replies kept. Restore brings it back exactly as it was, and Delete for good (which asks again) is the only thing that removes it permanently. A deleted request drops out of every list, reminder, the calendar and the expected costs, suppliers who open their link are told it is closed, and an emailed quote is never matched to it. Needs supabase/job-orders-deleted.sql run once on each database; until it has been run, Delete refuses and says so rather than deleting something that cannot be brought back.' },
  { at: '2026-10-16T19:00:00+01:00', title: 'Price request email: tell suppliers they can forward their own quote', detail: 'The email a supplier gets when you ask for a price now has its own box under the Give your price button, Use your own quoting system?, saying they can forward or email their quote (a PDF or a photo) from their own system to your companys quotes address with the PO number on it, and that they do not need to fill in the form as well. Before, this was one small grey line. The same wording is in the message you copy or send by WhatsApp and on the page the supplier opens. The box only shows when your quotes address is set up. No SQL needed.' },
  { at: '2026-10-16T17:00:00+01:00', title: 'Back Office: phases you add yourself are no longer removed', detail: 'A phase added by hand in Back Office, Phases and Tasks (one that is not part of the built-in list) was being deleted, with its sub-phases and tasks, the next time Back Office was opened, because the automatic tidy-up took it for a leftover old phase. That tidy-up now only removes built-in phases the app has retired and never touches a phase the company added itself. A phase already lost this way has to be added again; quotes that used it keep their own copy. No SQL needed.' },
  { at: '2026-10-16T15:00:00+01:00', title: 'Back Office allowances: day rate or hourly rate', detail: 'A sub-phase set to Allowance (the General Preliminaries roles such as Foreman, Projects Manager and Quantity Surveyor) can now be priced three ways, chosen under Priced as: one flat amount as before, a day rate, or an hourly rate. A day or hourly rate takes the rate and a typical number of days or hours, shows the total, and comes into a quote as one line (number times rate) that can be changed for that job. Changing how an allowance is priced clears its amount so an old flat figure is never taken as a rate, and existing flat allowances are unchanged. No SQL needed.' },
  { at: '2026-10-16T12:00:00+01:00', title: 'Quote: rename a phase or room', detail: 'A main phase header in a quote could not be renamed: the app finds a phase by its name, so after the first letter typed the box was rebuilt and lost the cursor. The name box now keeps what you type and applies the new name when you click away or press Enter (Escape puts the old one back). Rooms are fixed the same way. Renaming only changes that one quote, never Back Office or the templates. A blank name is ignored, a name already used in the same quote is refused with a message instead of silently merging two phases, and a renamed phase keeps whether it was open or closed. No SQL needed.' },
  { at: '2026-10-16T09:00:00+01:00', title: 'Phone: bigger small text', detail: 'On a phone (a touch screen up to about 520 pixels wide) the small writing in the main app is a step bigger: notes and hints that were 9 to 11 pixels are now 12 to 13, ordinary text is about a point bigger, and small labels, table headings, status badges and small buttons are lifted too. The cost-type labels in a quote (Labour, Materials and so on) are a little bigger as well. Names, headings and large text are unchanged, and tablets and computers look the same. No SQL needed.' },
  { at: '2026-10-15T22:00:00+01:00', title: 'Emailed quotes: cleaner note', detail: 'When a suppliers emailed quote is read, only what the supplier wrote is kept as their note. The apps own remark that the quote was only read as a total is shown on its own line, and no longer appears in quotation marks as though the supplier had written it. No SQL needed.' },
  { at: '2026-10-15T21:00:00+01:00', title: 'Company email address now uses a hyphen', detail: 'Each companys own quotes and documents address now has its code after a hyphen, for example quotes-ab12cd34@buildospro.ai, instead of a plus sign. Every mail system accepts a hyphen, and the mail host treats it as an ordinary address that its catch-all rule delivers. Addresses with the older plus form are still read. No SQL needed.' },
  { at: '2026-10-15T20:00:00+01:00', title: 'Emails received log, and faster reading of emailed documents', detail: 'Settings, under Your email addresses, now has an Emails received list: the latest emails that reached your quotes or documents address, with what the app did with each (quote added to a request, quote waiting to be placed, filed in the Documents inbox, no attachment, unknown address, or a problem and why). Emailed documents are also read faster: the check for whether it is a supplier quote and the normal document reading now run side by side instead of one after the other, so an emailed invoice does not run into the hosts time limit. Needs the new section at the end of supabase/quote-inbox.sql run once on each database.' },
  { at: '2026-10-15T18:00:00+01:00', title: 'Suppliers can email their own quote', detail: 'A supplier who would rather use their own quoting system can now email their quote, with your PO number on it, to your quotes email address (shown in Settings under Your email addresses, and in every price request email and message). The app reads the PDF or photo, works out which price request and which supplier it is from using the PO number and who sent it, and adds it as their reply, marked Read by the app, so please check it, with a link to view their original. Approve stays switched off until you press Looks right. A quote that has no PO number, or that the app cannot place with confidence, waits in an Emailed quotes to place box under Jobs, Price requests (and on your dashboard) for you to choose the request and supplier. A quote that is not set out item by item like your request is kept as a total. You can also drop a quotes PDF onto a supplier yourself with Add their own quote (PDF). Invoices and receipts emailed to the same address still go to your Documents inbox as before. Every company has its own code in the address (quotes+code@), so many builders can share one quotes address. Needs supabase/quote-inbox.sql run once on each database and the quotes email address set on the host.' },
  { at: '2026-10-15T15:00:00+01:00', title: 'AI quoting fits on a phone', detail: 'The AI scope screen was three columns side by side, so on a phone or a tablet held upright the AI writer was cut off. On a narrow screen it now shows two tabs, Scope of works and AI writer, one at a time at full width (nothing is lost when you switch), with the job setup folded into a box you tap to open, a taller AI writer, and the Generate Scope, Build Estimate and Scope Only buttons wrapping onto a second line. On a wide screen it is still three columns. Also on a phone, the dark phase bars in a quote now wrap so the phase name stays visible next to the price and the Room and Sub-phase buttons, and the long cost-type labels such as Subcontractors fit inside their tiles. No SQL needed.' },
  { at: '2026-10-15T12:00:00+01:00', title: 'Notifications on your phone and tablet', detail: 'Settings now has a Notifications area at the top. Press Turn on notifications on this device on each phone or tablet and allow notifications when asked, and the app alerts you even when it is closed: when a supplier replies to a price request, when a subcontractor sends a site note or a timesheet, and with a short morning summary (only if something needs you) of late deliveries, invoices that have not arrived, overdue invoices and prices waiting to be compared. Tapping an alert opens the right screen. There is a Send me a test button, a switch for each kind of alert and a master switch to pause them all. On an iPhone or iPad the app has to be added to the Home Screen first, and Settings explains how. Alerts go to the company owner. Needs supabase/push-notifications.sql to be run once on each database, and four settings (the notification keys, subject and the daily-summary secret) to be added to the host.' },
  { at: '2026-10-15T10:00:00+01:00', title: 'Price requests: easier to find the replies', detail: 'The email you get when a supplier replies to a request for prices now has a See the prices button that opens the request itself: the jobs Orders window, or the Price requests list when it is not for a job yet, instead of just the Jobs page. The Price requests button is now also in the Jobs header on a phone or tablet; before it was only on the computer. No SQL needed.' },
  { at: '2026-10-14T20:00:00+01:00', title: 'Price requests: linked products asked for in their own unit; saves without the new column', detail: 'When a calculators materials list is sent to suppliers for prices, a line that is linked to a Back Office product is now asked for as that product: its name, in its own unit, and for a product sold in packs or rolls the number of whole packs. A line the calculator counts in square metres that is linked to a product sold per item is now asked for as that many items, not as square metres. Lines with no link are asked for as the calculator has them, and the calculators own print and CSV lists are unchanged. Also, if a database has not yet had supabase/job-orders-lines.sql or job-orders-materials.sql run, an order or price request now still saves, with the list of items written into its details (one price for the whole list), and a message names the file to run, instead of failing with a database error.' },
  { at: '2026-10-14T18:30:00+01:00', title: 'Subcontractor portal: bigger, clearer text', detail: 'The small writing on the subcontractor portal is larger. The Your next days on site card on the dashboard and the My schedule page have bigger day names, job lines, addresses and tags, and the summary card labels are bigger. The whole portal is also scaled up a little: Normal text is about 8 percent larger than before and Large about 25 percent larger (it was 15), so the timesheet and notes pages get a bit bigger too. A subcontractor can still switch between Normal and Large from the paintbrush in the top corner, under Your look. No SQL needed.' },
  { at: '2026-10-14T17:00:00+01:00', title: 'Subcontractor portal: times on a split day', detail: 'When a subcontractor chooses Split day in Add my time, the form now asks for the start and finish time of each half: first job start and finish, and second job start and finish. They are optional, pay is still two half days, and each halfs times go to the office with its timesheet. A half that finishes before it starts is refused, and so are two halves that overlap; halves that meet exactly are fine and either job can be the morning. No SQL needed.' },
  { at: '2026-10-14T15:00:00+01:00', title: 'Calendar: progress on the bars and one-click 100%', detail: 'A task that is part finished now shows it on the Calendar: the finished part of its bar is drawn darker, so a task at 80 percent reads as about four fifths filled (spread correctly over the weeks it runs), and the bar label, Day view card, phone and tablet list and task panel say the percentage. A task at 100 percent looks as before, hatched and marked Complete. In the task panel there is now a green 100% done button that marks the task done and saves straight away with no typing, plus 25, 50 and 75 percent buttons that fill the box, and each unfinished task card in the Day view has a small 100% button. The jobs own Gantt chart is not changed. No SQL needed.' },
  { at: '2026-10-14T13:00:00+01:00', title: 'Price requests: pick the items from your products', detail: 'A request for prices on materials now has an Items to be priced list that you build from your Back Office products, with a quantity for each, or by typing a line in by hand. A product that is not in Back Office can be created from the same product list with New Product, which saves it to Back Office and adds it to the list. A product added twice adds to its quantity. It is there in a jobs Orders window (Ask for a price, then Materials delivery) and on a calculators Prices window, where the calculators materials start as the list and can be changed, with products or lines added. The email, WhatsApp message and order confirmation now build their lists from the items, and the detail box on a materials request is a note for the supplier. No new SQL needed beyond job-orders-lines.sql.' },
  { at: '2026-10-14T11:00:00+01:00', title: 'Price requests: a price for each item', detail: 'A request for prices made from a calculators materials list now lets the supplier price every item separately. Their page shows a card for each item with its quantity, a unit price box with the line total worked out, a tick for cannot supply and a note or alternative, then a delivery charge and a running total saying how many items are priced. You see each suppliers total with how many items they priced, and a Compare line by line table with items down the side and suppliers across, the cheapest for each item shaded green, delivery and total underneath, plus what buying each item from whoever is cheapest would come to for information. An answer that leaves items out is never flagged as the cheapest, because it would always look cheaper. Approving still takes one suppliers whole answer. Needs supabase/job-orders-lines.sql to be run once on each database; requests made before still work with one total price.' },
  { at: '2026-10-14T09:00:00+01:00', title: 'Invoices: stage payments now go to Xero at their percentage', detail: 'An invoice line set to a percentage of its price (a stage payment such as 40 percent of Foundations) was totalled correctly in the app but sent to Xero, and shown on the printed and emailed invoice, at the full price. It is now sent and shown as the part: the description says for example Foundations (40% of 10,000.00) and the amount is the 40 percent. Lines at 100 percent and ordinary lines are unchanged. An invoice already sent to Xero with the wrong amounts can be pushed again to correct it. No SQL needed.' },
  { at: '2026-10-13T22:00:00+01:00', title: 'Calculators: ask suppliers for prices on a materials list', detail: 'Every calculator with a materials list now has a Prices button next to Print and CSV. It asks one or more suppliers or merchants to price the whole list: each gets their own link by email or WhatsApp and gives one price for everything, with their delivery date and how long the price stands, no login. They see what to buy and how much, with waste allowed for, never your own prices, and only the area of the job. It works before there is a job, while you are pricing a quote: those requests are kept under Jobs, Price requests, and you attach one to a job when it is won, then approve a price like any other request. A typed area such as Tooting, SW17 is now shown to suppliers whole. Needs supabase/job-orders-materials.sql to be run once on each database.' },
  { at: '2026-10-13T21:00:00+01:00', title: 'Calendar: deliveries and collections from Orders', detail: 'The Calendar now shows each orders delivery day, and the collection day of skips, portaloos and plant, as small chips on their day in the month, week and day views and in the phone and tablet list. A dashed chip is an order not yet sent to the supplier, a struck-through faded chip has arrived or been collected. Click a chip to see the date and time slot, status, job, full site address, site contact, access notes and expected cost, mark it arrived or collected straight from the calendar, or open that jobs Orders. Dates are changed in the jobs Orders, and the chips are hidden while the calendar is filtered to one person. No SQL needed.' },
  { at: '2026-10-13T20:00:00+01:00', title: 'Dashboard: margins count expected costs, and order reminders', detail: 'The Job margins card on the dashboard now includes orders on account that have no invoice yet, so a job with a skip or hire on order shows its lower margin straight away, with a note of how much is expected. Needs your attention now also lists orders: a price you approved but have not sent the order for, suppliers who have replied to a price request, a cost that looks like the invoice for an order (so the margin is not counting both), a delivery date that has passed with no word that it arrived, a supplier invoice that was expected by now, and hire still on site longer than planned. Click one to open that jobs Orders window. The on-site-too-long warning now only shows once an order is marked delivered.' },
  { at: '2026-10-12T22:00:00+01:00', title: 'Job orders: ask suppliers for a price with a no-login form', detail: 'In a jobs Orders window, Ask for a price lets you ask one or more suppliers to quote for a skip, hire or materials. Each supplier gets their own secret link by branded email or WhatsApp and opens a simple page, no login, showing what is wanted, when and only the area of the job, never the street. They give a price excluding VAT (one price, per day or per week), their earliest delivery date, how long the price stands and any notes, or say they cannot do it, and can change their answer until you decide. You are emailed when a reply arrives. The replies sit side by side with the cheapest flagged and hire worked out for the planned time. Approve this price turns the request into an order with the same PO number at their price and date, counts it as an expected cost straight away (or a paid cost for materials paid at once), marks the other suppliers as not chosen, and Send confirmation then sends the supplier the full order with the full address and the PO to quote on the invoice. Needs supabase/job-orders-quotes.sql to be run once on each database.' },
  { at: '2026-10-12T20:30:00+01:00', title: 'Job orders: skips, hire and materials with a PO number and expected costs', detail: 'Every job now has an Orders button (on the job card and in the Costs window). Raise a skip, portaloo, plant hire, materials or other order with the supplier, dates, site address and price; it gets a PO number (PO-0001, counting up) and can be sent by branded email (logo, company details, please quote the PO on your invoice) or by a ready-written WhatsApp message. Orders on account count as expected costs straight away: the Costs window has a Still to come box and shows Margin so far and Margin including expected costs, turning amber or red against the margin you quoted. Hire is priced by rate and time on site with an overrun warning. When the supplier invoice arrives you add it from the order, or match it to a cost already in the job, and the expected cost stops counting; the app suggests a match but never does it on its own. Materials marked paid when ordered create the paid cost at once. VAT on costs made this way is assumed at 20 percent. Needs supabase/job-orders.sql to be run once on each database. The supplier price form, overdue-invoice reminder and calendar deliveries are still to come.' },
  { at: '2026-10-12T19:41:00+01:00', title: 'Subcontractors: timesheets grouped by week', detail: 'On the Subcontractors page, the Weekly Timesheets list now has a heading for each week (Week of the dates, how many people and days, any pending, and the week total), newest first, with a clear gap between weeks and each subcontractor card for that week underneath in name order. Click a week heading to fold the whole week away.' },
  { at: '2026-10-11T19:55:00+01:00', title: 'Pitched roof covering: flashing choice, soakers and chase at a wall', detail: 'In Roof Coverings (pitched), when the roof meets an existing wall you can now choose the flashing: code 4 lead, code 5 lead, lead-effect or a GRP lead-effect trim. Lead flashing up a sloping edge (a gable or hip end against a wall) gets a lead soaker at every course, a lean-to high wall gets an apron flashing with none. There is a materials line for the chase (lead wedges, mortar and sealant) and a labour line for the roofer cutting the chase, fitting the soakers and pointing in. The customer description names the flashing. All rates and hours are samples.' },
  { at: '2026-10-11T19:42:00+01:00', title: 'Product links: same in every calculator, decoration links shared by room', detail: 'Checked every calculator: all use the same product pop-up. In the decoration calculator a product link is now to the kind of material (for example wall paint), so one link covers every room and every quote instead of one room only. Litres and kilos are understood as units and a tin or tub size (5L, 5kg) is read from the product name, with whole-pack pricing. The computed lump-sum decoration lines (dust sheets and prep sundries) cannot be linked.' },
  { at: '2026-10-11T19:38:00+01:00', title: 'Calculators: search pop-up to link a product, and roll or pack sizes', detail: 'The Link to a product button on a calculator cost line now opens a pop-up with a search box (name, category or supplier) and shows what that line would cost from each product, marking the cheapest of the similar ones. A product sold in another unit, such as a roll of breather membrane, can be linked by saying how much of the line unit one covers (read from names like 1m x 50m roll where it can), and the line then pays for whole packs: 20 m from a 50 m roll costs the whole roll, while a 20 m roll costs just that. A linked line shows what it buys. Pack sizes need supabase/calculator-rate-links-pack.sql to be run once on each database; without it only same-unit products link, as before.' },
  { at: '2026-10-11T19:29:00+01:00', title: 'A margin of its own for one sub-phase', detail: 'In a quote, the Margin figure in a sub-phase header is now a box you can type in, so one sub-phase can have its own margin instead of the quote overall markup. A sub-phase with its own margin shows its box in green with a reset arrow that goes back to the quote margin; the quote-wide Markup slider does not change it. Sub-phases priced by a calculator still set their margin in the calculator. The margin flows through to the client quote, PDF, portal and the breakdown cards, and clients never see the percentage.' },
  { at: '2026-10-11T19:12:00+01:00', title: 'Client portal: unsent quotes and draft invoices are hidden', detail: 'A client now only sees a quote once it has been sent (and afterwards once they have approved or rejected it), and never a draft invoice. Before this, every quote and invoice for that client showed in their portal whatever its status, so a quote you were still working on could appear, and could even be approved while it was only saved. A client can now only approve a quote that has been sent, comments and attachments on an unsent quote are closed to them, and your preview of the portal follows the same rule. The database part is supabase/portal-hide-unsent.sql, which has to be run once on each database (an undo file is next to it).' },
  { at: '2026-10-11T18:00:00+01:00', title: 'Decoration calculator: drying time and days on site', detail: 'The Internal decoration calculator now adds a drying time and return visits allowance, 10% of the painter hours by default (a slider from 0 to 30%), as its own labour line so it can be seen and changed. It also shows an estimate of the days on site: the longer of the painter time in 8 hour days and the longest chain of drying steps in any one room (filler, mist coat or sealer, then each coat, and primer, undercoat and topcoats on woodwork), with the reason for each room on hover. The days figure is for planning and does not yet feed the Gantt.' },
  { at: '2026-10-11T17:40:00+01:00', title: 'Take-off: Decoration now opens the Internal decoration calculator', detail: 'In Take-off, a Decoration area with the Internal Wall and Ceiling Painting sub-phase picked now shows the calculator card and an Open calculator button, like the roof. The drawn area is only a marker on the plan; the rooms are added in the calculator, and its price and description go to the quote when you send the take-off. A Sub-Phase picked before drawing carries onto the area. Decoration items drawn earlier with a flat task keep working as they did until their sub-phase is changed.' },
  { at: '2026-10-11T17:33:00+01:00', title: 'Quotes open with their phases collapsed', detail: 'When you open a quote, saved or new, every phase now starts collapsed, and the sub-phases inside start collapsed too, instead of everything being open. This also applies when the AI, a template or a Take-off import fills a quote in. A single sub-phase you add yourself stays open. Expand All and Collapse All work as before.' },
  { at: '2026-10-11T17:29:00+01:00', title: 'Add Sub-Phase opens on the phase you are in', detail: 'Adding a sub-phase from inside a phase on a quote (for example Decoration) now lists the sub-phases of that phase first, with a tick on any already in the quote, and a link to show the sub-phases of every other phase. Searching still looks through all phases.' },
  { at: '2026-10-11T17:19:00+01:00', title: 'Scope box starts small', detail: 'The scope of works box on New Quote and Quick Quote now starts about four lines tall and scrolls, instead of growing to show all its text. Drag its bottom or right edge to see more. The full-screen AI scope writer still grows with its text.' },
  { at: '2026-10-11T17:04:00+01:00', title: 'New calculator: Internal decoration, room by room', detail: 'The Internal Wall and Ceiling Painting sub-phase under Decoration now has a calculator. Add each room, give its size, doors and windows, then say what state its walls and ceiling are in (new plaster, painted and in good order, painted but flaking or patchy, or wallpapered that has to be stripped) and how much filling and sanding they need. It prices the preparation, a mist coat on new plaster, sealer, stripping with steamer hire, the paint from the area and number of coats, and the painter time, plus the skirting boards, architraves, picture rails, doors and window frames if they are painted too. Cost and paint are shown room by room, with a Copy button for matching rooms. All rates and hours are sample figures to check against real jobs. The old simple tasks under that sub-phase are now replaced by the calculator.' },
  { at: '2026-10-11T16:20:00+01:00', title: 'Scope of works box can be resized', detail: 'The scope of works box has a grip on its bottom edge and right edge: drag the bottom one to make the box taller or shorter, the right one to make it narrower or wider, or the corner for both. It works with a mouse or a finger. The size is not remembered between visits.' },
  { at: '2026-10-11T16:12:00+01:00', title: 'Scope of works: bold, underline and bullets, no more stars', detail: 'The scope of works box (New Quote, Quick Quote and the AI scope workspace) is now a small word-processor with Bold, Underline and Bullet list buttons, also Ctrl+B and Ctrl+U. It shows real bold, underline and bullets instead of asterisks, and the online quote, printed and emailed quotes and the client portal show the same formatting, so the stars the AI used to leave around headings no longer appear. The contract and the invoice description get the words without formatting. In the PDF first-page summary only a bold phrase at the start of a line counts as a heading. Pasting keeps bold, underline and bullets but drops fonts and colours from other places.' },
  { at: '2026-10-11T15:34:00+01:00', title: 'AI review: suggestions on a normal sub-phase now leave a note', detail: 'On a sub-phase that is not priced by a calculator, a suggestion added from the AI review still goes in as a line at 0 pounds in its cost list, but it now also leaves a note on the sub-phase saying what was added, with a Price it button that opens that cost list. The review pop-up explains this before you add anything, and the sub-phase no longer closes itself after a review if notes are waiting.' },
  { at: '2026-10-11T12:55:00+01:00', title: 'Quote breakdown: cards, margin by phase, comparison with past jobs', detail: 'The breakdown at the bottom of a quote is now a set of cards: Your cost, Your margin (in pounds, as a percentage on cost and of the sell price), Sell price and your target margin (the quote margin setting); a card for each cost type (labour, materials, plant, subcontract, other) with its share of cost and its margin; and Margin by phase, green, amber or red against your target, where you can tap a phase to see its sub-phases. Below that, Compared with your similar jobs checks each sub-phase against the same sub-phase on your own won quotes and says where this one is much cheaper or dearer and which cost type accounts for it, and Things to look at lists plain flags (a sub-phase well under your target margin, sub-phases with nothing priced, no plant or contingency priced). Won quotes are now remembered with the real cost and the own margin of each sub-phase, and rejected quotes are remembered as lost, so the comparison gets better as you win jobs. Everything is ex VAT and the labour-by-trade tables are still underneath.' },
  { at: '2026-10-11T12:35:00+01:00', title: 'AI review suggestions on calculator sub-phases become notes', detail: 'On a calculator sub-phase, a suggestion from the AI review is now kept as a note ("+ Add as note") shown on the sub-phase and at the top of the calculator when you recalculate, with a tick and a remove button, instead of a hidden cost row that Recalculate wiped. Sub-phases without a calculator still get a visible cost row. No SQL needed.' },
  { at: '2026-10-11T12:26:00+01:00', title: 'AI review: fixed the "not valid JSON" error', detail: 'The AI phase review could end with a "not valid JSON" message when it ran past the host\'s time limit. It now uses the faster AI model with its own time limit, and shows a plain "took too long, try again" message if the host ever sends an error page instead. No SQL needed.' },
  { at: '2026-10-11T12:19:00+01:00', title: 'Description: say it, the AI writes it; review checks your price', detail: 'The Description box on a quote sub-phase has a "Say it" mic and a "Write it" button: dictate or type a few rough words about the work and the AI writes the short scope-of-works line printed under the sub-phase name (never any price, cost or profit wording), with Undo. The AI review (robot button) now reads that description, what is priced for it and the margin, and starts with a price check (looks low, about right or high, with reasons) and flags anything the description mentions that is not priced. Each use counts towards your AI allowance. No SQL needed.' },
  { at: '2026-10-11T11:53:00+01:00', title: 'Quote phases: tidier layout', detail: 'On a quote, each sub-phase now has one total: its Cost, Margin and Sell (all ex VAT) sit in the sub-phase header row when it is open, and the separate costing box is gone. A room shows its own subtotal only when it has more than one sub-phase, and the phase total says ex VAT. The header row wraps on a narrow tablet or phone. Layout only; no prices change. No SQL needed.' },
  { at: '2026-10-11T11:46:00+01:00', title: 'Margin: one per sub-phase, shown ex VAT', detail: 'A calculator\'s profit % is now that sub-phase\'s own margin (% added on top of cost) instead of a Profit cost line, and it replaces the quote\'s overall markup for that sub-phase, so the two no longer stack. Each sub-phase shows Cost (ex VAT), Margin n% on cost and Sell (ex VAT). Quotes saved before this keep their prices until a calculator sub-phase is saved again; clients still never see the margin. No SQL needed.' },
  { at: '2026-10-11T11:24:00+01:00', title: 'Clients never see profit on calculator items', detail: 'A calculator sub-phase\'s own "Profit" row and its cost-rate notes (such as "110 nr @ £0.80/nr (10% waste)") no longer appear anywhere a client sees the quote: the client view, detailed view, online quote, printed quote and PDF. The profit is spread across the other rows so phase and quote totals do not change, and your own quote screens still show it. The PDF\'s per-item prices now use each item\'s full price. No SQL needed.' },
  { at: '2026-10-11T11:18:00+01:00', title: 'Saved quotes keep their prices; Refresh button removed', detail: 'The "Refresh from Back Office" button is removed from the quote toolbar: a new calculator starts from the current Back Office prices and a saved quote is a record that only changes when you change it. A calculator opened from a saved quote now keeps the prices it was saved with (before, a line linked to a Back Office product could quietly take today\'s price); a linked line offers a "↻ now" button to update it on request. No SQL needed.' },
  { at: '2026-10-11T11:05:00+01:00', title: 'Quote sub-phase: clearer labels', detail: 'The "Task Name" box on a quote sub-phase is now labelled "Description" (shown under the sub-phase name on the quote), and the sub-phase name says on hover that renaming it is for this quote only and does not change Back Office. Labels only. No SQL needed.' },
  { at: '2026-10-11T11:01:00+01:00', title: 'Quote phases: tidier buttons', detail: 'The extra "+ Sub-phase" buttons inside a phase (in each room row, and under a list with no room) are removed, as is the "+ Task" button that did nothing. The "+ Sub-phase" in the phase header is the one way to add; when the phase already has rooms, its picker now has a "Put it in" dropdown to choose the room. No SQL needed.' },
  { at: '2026-10-11T10:49:00+01:00', title: 'Quote: "↑ BO" button removed', detail: 'The "↑ BO" button on a quote sub-phase (which wrote that sub-phase\'s prices over the Back Office default rates) has been removed, so a one-off price in a quote can no longer change the standard rates by accident. Default rates are edited in Back Office. No SQL needed.' },
  { at: '2026-10-11T10:46:00+01:00', title: 'Quote sub-phase: one way into the calculator', detail: 'The extra Calculator button in a sub-phase header is gone: the Open Calculator / Recalculate button in the sub-phase card is the way in, and Recalculate opens the calculator as you left it. A Task Name you have typed over is no longer overwritten when the calculator is saved again. No SQL needed.' },
  { at: '2026-10-11T10:35:00+01:00', title: 'Saved calculators open again as you left them', detail: 'An assembly calculator now keeps what was typed into it when you press Save & Price, with the quote sub-phase or the Take-off item, so opening it again shows it as you left it and you can edit and save again (before, it opened blank). The Task Name on a sub-phase is now a two-line description box that can be cleared and rewritten without the original wording coming back while you type. Calculators saved before this open fresh once. No SQL needed.' },
  { at: '2026-10-11T10:21:00+01:00', title: 'Tablet and installed app: files open with a Close button', detail: 'On a tablet, a phone or the installed app, PDFs, pictures, attachments, printable pages (materials lists, quote previews, invoices, job reports) and links to files or the app\'s own pages now open full screen inside the app with a Close button (Esc and the device Back also close it), instead of a new tab with no way back. Printable pages have a Print button. Desktop browsers are unchanged. No SQL needed.' },
  { at: '2026-10-11T10:11:00+01:00', title: 'AI quote prices the electrical installation', detail: 'When the scope describes electrical work, the AI quote now prices the electrical installation room by room with the calculator: the rooms named, the points stated (a room named with no points gets its usual set, listed in the review note), special fittings such as a chandelier, and whole-house items such as a new consumer unit. It never adds a room or count the scope does not mention. The calculator opens showing the same rooms, and the scope chat now asks about electrics and writes them room by room. No SQL needed.' },
  { at: '2026-10-11T10:00:00+01:00', title: 'Take-off: electrical points on the plan', detail: 'In the Electrics phase a new tool places electrical points on the plan: pick a kind of point (sockets, switches, lights, extractors, alarms, data), click where it goes, and it is counted in its room (taken from a named floor area it sits in, or typed). Points can be moved, changed, deleted or marked as a special fitting. They feed the electrical installation calculator, whose room counts follow the plan until typed over; the calculator now keeps what you set with the Take-off project, and warns when the plan has changed since it was priced. No SQL needed.' },
  { at: '2026-10-10T20:15:00+01:00', title: 'New calculator: Electrical installation', detail: 'Prices the whole electrical installation room by room, per point at an electrician\'s all-in rate: add a kitchen, bathroom, bedroom and so on, each with its usual points to adjust. A situation percentage (refurbishment, occupied house, hard to reach, listed building) can be set for the job or a room; special fittings such as a chandelier are an extra install charge, client-supplied or ours; a room can be priced by the day; whole-house items cover the consumer unit, testing and certificate and extra circuits. A new sub-phase under Electrics (restore the Electrics phase first if it was deleted, then open Back Office once). Not yet in Take-off. No SQL needed.' },
  { at: '2026-10-10T19:58:00+01:00', title: 'AI writer: faster voice and resizable', detail: 'The read-aloud voice has a speed picker (default 1.15 times, up to 2 times). The AI writer pop-up can be dragged wider or taller by its left and top edges, or expanded with a button, and the AI writer column on the full AI quote screen can be dragged wider. Sizes are remembered on each device. No SQL needed.' },
  { at: '2026-10-10T19:49:00+01:00', title: 'AI scope chat can read aloud', detail: 'A speaker button on each reply from the AI scope chat (the interview questions and the finished scope) reads it out with the voice built into your device, with a Stop button and, where the device has several voices, a voice picker. It stops when you send a message or start dictating. Free, and nothing is sent anywhere. No SQL needed.' },
  { at: '2026-10-10T19:41:00+01:00', title: 'Cavity wall: labour starts sized from the wall', detail: 'The cavity wall calculator now opens with one bricklayer labour line (1 hour per m2 of wall, following the wall size until you edit it), instead of a typed 12 hours with no trade picked. This is the same labour the AI quote uses, so the AI price and the calculator now agree. No SQL needed.' },
  { at: '2026-10-10T19:38:00+01:00', title: 'AI quote prices the foundation calculators', detail: 'When the scope states the sizes, the AI quote now prices strip foundation, trench fill, raft, pads, piled foundation and underpinning with each calculator\'s standard settings (cavity walls already worked this way), and flags them for review. Opening the calculator from the quote shows the same sizes. The scope chat now asks about foundation type and sizes and writes them as numbers. With no sizes stated the line stays "Not yet calculated". No SQL needed.' },
  { at: '2026-10-10T19:05:00+01:00', title: 'Calculators: link rates to Back Office prices', detail: 'In any calculator, a materials line can be linked to a Product and a plant line to a Plant item (same unit only). A linked line uses that item\'s price and follows it when it changes; unlink puts the sample rate back. Labour already uses your trades. Needs supabase/calculator-rate-links.sql to save links.' },
  { at: '2026-10-10T18:54:00+01:00', title: 'New calculator: Underpinning', detail: 'Prices traditional mass concrete underpinning in pins from the drawn line of wall: hand digging, skips, concrete, dry pack and shuttering, with optional props and reinforcement, labour, a quote description and a section drawing. A new sub-phase under Foundations; in Take-off, set Foundation Type to Underpinning.' },
  { at: '2026-10-10T18:43:00+01:00', title: 'New calculator: Piled Foundation', detail: 'Prices piles (a subcontract price per metre plus a rig charge, count from the spacing or typed) with a shuttered, caged ground beam on top, from the drawn line, with labour, a quote description and a section drawing. A new sub-phase under Foundations; in Take-off, set Foundation Type to Piled Foundation. This completes the five foundation calculators: strip, trench fill, raft, pad and piled.' },
  { at: '2026-10-10T18:28:00+01:00', title: 'New calculator: Pad Foundations', detail: 'Prices pad foundations from the number of pads and their size (more groups for different sizes): pits, blinding, concrete, soil away, with optional formwork, reinforcement and column starters, plus labour, a quote description and a section drawing. A new sub-phase under Foundations; in Take-off, a rectangle in Foundations set to Pad Foundations opens it.' },
  { at: '2026-10-10T18:19:00+01:00', title: 'Take-off: raft foundations drawn as a shape', detail: 'A rectangle or polygon in Foundations set to Raft Foundation (or the Raft sub-phase picked first) opens the Raft calculator, sized from its box. A foundation line no longer gets the raft calculator by mistake (it only gets strip or trench fill).' },
  { at: '2026-10-10T18:13:00+01:00', title: 'New calculator: Raft Foundation', detail: 'Prices a raft from its footprint: bulk dig and soil away, hardcore, blinding, DPM, optional insulation and edge beam, edge formwork, mesh and concrete (optionally pumped), with labour, a quote description and a section drawing. A new sub-phase under Foundations. Not yet opened from Take-off.' },
  { at: '2026-10-10T18:07:00+01:00', title: 'New calculator: Trench Fill Foundation', detail: 'Prices a trench filled with concrete to a set distance below ground, with the wall up to DPC, from the drawn line. A new sub-phase under Foundations, and the default Foundation Type in Take-off now opens this calculator. The labour panel wording now says foundation / parapet wall instead of roof.' },
  { at: '2026-10-10T17:58:00+01:00', title: 'Take-off: strip foundations priced by their calculator', detail: 'A drawn foundation line set to Strip Footing is priced by the Strip Foundation calculator (summary card and full-size window), and a sub-phase picked before drawing carries onto the line. Open Back Office once so the new sub-phase appears in your list.' },
  { at: '2026-10-10T17:46:00+01:00', title: 'New calculator: Strip Foundation (Traditional)', detail: 'Prices a strip foundation from its length: the trench and machine, soil taken away, concrete, blockwork up to DPC (solid or cavity filled), DPC, backfill and labour, with a quote description and section drawing. A new sub-phase under Foundations. Not yet opened from Take-off.' },
  { at: '2026-10-10T17:31:00+01:00', title: 'Owner area: one Change log', detail: 'Software updates and every change to Phases & Tasks now appear together in one list, with filters and search.' },
  { at: '2026-10-10T17:22:00+01:00', title: 'Phase change history', detail: 'The database now records every change to Phases & Tasks: what changed, before and after, who and when. Read it in the Owner area. Needs supabase/bo-change-log.sql.' },
  { at: '2026-10-10T16:46:00+01:00', title: 'AI wording on every sub-phase', detail: 'A "What this covers (for the AI)" box on each sub-phase, with suggested wording for all the built-in ones. The AI quote reads it to choose the right sub-phase. Needs supabase/sub-phase-ai-hint.sql to save your own wording.' },
  { at: '2026-10-10T16:41:00+01:00', title: 'AI quote prefers the calculators and groups phases correctly', detail: 'Each calculator sub-phase is described to the AI, which is told to prefer it over a general phase for the same work. A phase is grouped under the main phase Phases & Tasks puts it in, not the one the AI guessed.' },
  { at: '2026-10-10T16:25:00+01:00', title: 'AI scope of works only covers the work described', detail: 'For a single element such as one wall, the scope no longer lists demolition, foundations, structure and every other default phase.' },
  { at: '2026-10-10T16:17:00+01:00', title: 'AI quote prices a cavity wall from its length and height', detail: 'The AI hands the size it heard to the cavity wall calculator, which prices the wall with its standard settings. Calculator sub-phases start at "Not yet calculated" instead of carrying leftover flat lines.' },
  { at: '2026-10-10T15:50:00+01:00', title: 'Deleted wall build-ups stay deleted', detail: 'Deleted External Walls, Floors, Foundations and Plastering build-ups and their layers are no longer put back, and edited layer names and prices are kept.' },
  { at: '2026-10-10T15:24:00+01:00', title: 'Your edits in Phases & Tasks stick', detail: 'Back Office no longer overwrites the names, order or units you set, and a deleted standard phase, sub-phase or task stays deleted, with a Restore list at the bottom. Needs supabase/bo-deleted-items.sql.' },
  { at: '2026-10-10T14:09:00+01:00', title: 'Standard job types are templates too', detail: 'Rear Extension, Loft Conversion and the rest appear in My templates, empty to start with and quoted the old way until you fill them in.' },
  { at: '2026-10-10T13:54:00+01:00', title: 'My templates', detail: 'Named templates built from the sub-phases in Phases & Tasks, offered when starting a manual quote. Prices, tasks and calculators stay in Phases & Tasks. Needs supabase/quote-templates.sql.' },
  { at: '2026-10-10T11:51:00+01:00', title: 'Subcontractor timesheets: full day, half day or split day', detail: 'A subcontractor can record a half day, or two jobs in one day (each a half day), so a short day is no longer paid as a full day.' },
  { at: '2026-10-10T11:15:00+01:00', title: 'Contacts: row Delete button removed', detail: 'Deleting is done from Tidy up contacts.' },
  { at: '2026-10-10T11:07:00+01:00', title: 'Contacts: deleted contacts stay deleted', detail: 'Xero sync no longer brings back a contact you deleted, optional archive in Xero, and a Tidy up contacts screen to remove many at once with a restore list. Needs supabase/deleted-contacts.sql.' },
  { at: '2026-10-09T20:00:00+01:00', title: 'Dashboard: drag to move and resize cards', detail: 'On a computer, drag a card to move it and drag its right-hand edge to resize it. Cards in a row are the same height.' },
  { at: '2026-10-09T17:57:00+01:00', title: 'Dashboard as a grid of cards', detail: 'Greeting, needs-attention, headline cards, this week on site, active jobs and job margins as cards you can arrange; layout remembered per login.' },
  { at: '2026-10-09T14:29:00+01:00', title: 'Documents: save as subcontractor fixed quote', detail: 'Creates the fixed quote with the emailed document attached, with no bill or job cost, then straight to adding payment stages.' },
  { at: '2026-10-08T16:14:00+01:00', title: 'Subcontractor portal: Talk buttons', detail: 'Dictate "Describe your day" and "What did you work on?" instead of typing.' },
  { at: '2026-10-08T15:59:00+01:00', title: 'Subcontractor notes: Talk button', detail: 'Dictate a note with the phone\'s speech recognition.' },
  { at: '2026-10-08T15:06:00+01:00', title: 'Contact panels by type', detail: 'Clients, subcontractors and suppliers each get the panel that suits them (quotes and jobs, timesheets and pay, spend and bills).' },
  { at: '2026-10-08T14:58:00+01:00', title: 'Contact panel: tidier header', detail: 'Name and window buttons on one line; no + Quote button for subcontractors.' },
  { at: '2026-10-08T14:51:00+01:00', title: 'Subcontractor portal: Fixed-price payments', detail: 'Payments is now "Fixed-price payments" and points day-rate and hourly subcontractors to Timesheets.' },
  { at: '2026-10-08T14:41:00+01:00', title: 'Deleting a portal-sourced weekly day removes the original', detail: 'It no longer reappears in the subcontractor\'s portal.' },
  { at: '2026-10-08T14:38:00+01:00', title: 'Subcontractor portal loads faster', detail: 'Main data, schedule and company calendar load together instead of one after another.' },
  { at: '2026-10-08T14:33:00+01:00', title: 'Subcontractor portal has its own app settings', detail: 'The home-screen icon opens the portal, and the builder\'s screens are no longer flashed to a subcontractor or client.' },
  { at: '2026-10-08T14:18:00+01:00', title: 'Approved portal timesheets go into the weekly timesheet', detail: 'Paid with the week like any logged day; the subcontractor sees approved, then paid.' },
  { at: '2026-10-08T14:01:00+01:00', title: 'Job note photos are more reliable', detail: 'Phone photos in odd formats are converted, clear reasons when a photo can\'t go, and a "Try the photo again" button.' },
  { at: '2026-10-08T13:52:00+01:00', title: 'New subcontractor notes are flagged', detail: 'A red "new" badge on a job\'s Notes button, NEW tags in the Activity Log, and a "Needs your attention" dashboard card.' },
  { at: '2026-10-08T13:19:00+01:00', title: 'Job pickers list jobs that are on site', detail: 'Subcontractor timesheet, notes and preview pickers use jobs that are active and not archived. Needs the updated SQL.' },
  { at: '2026-10-08T13:15:00+01:00', title: 'Job notes: accept the jobs the portal offers', detail: 'Clearer error messages on the notes page.' },
  { at: '2026-10-07T20:26:00+01:00', title: 'Subcontractor Company Calendar: week strip', detail: 'Seven day buttons with dots and a card for the chosen day replace the month grid.' },
  { at: '2026-10-07T20:21:00+01:00', title: 'Subcontractor portal: Add my time and Timesheets split', detail: 'Add my time opens just the form; recorded timesheets have their own page.' },
  { at: '2026-10-07T20:15:00+01:00', title: 'Subcontractor portal home: tiles', detail: 'Tiles open their own page with a Home button; the builder\'s preview matches.' },
  { at: '2026-10-07T20:10:00+01:00', title: 'Subcontractor portal redesign', detail: 'A big readable home screen with stat cards and app-style tiles, and a "Your look" sheet with four tile styles and Normal or Large text.' },
  { at: '2026-10-07T20:00:00+01:00', title: 'Subcontractor job notes with photos', detail: 'Notes and photos against a job, landing in the job\'s Activity Log labelled with their name.' },
  { at: '2026-10-07T19:53:00+01:00', title: 'Calendar tab renamed Company Calendar', detail: 'Shown as plain Calendar only when the company view is switched off for that person.' },
  { at: '2026-10-07T19:45:00+01:00', title: 'Task days: clicking a day picks just that day', detail: 'Fixes Friday appearing to move to Monday; "Every day" is its own button.' },
  { at: '2026-10-07T19:32:00+01:00', title: 'Big Add my time button on the subcontractor dashboard', detail: 'The builder\'s preview shows it too.' },
  { at: '2026-10-07T19:22:00+01:00', title: 'Simpler subcontractor timesheet form', detail: 'Job, date, start, finish and lunch with hours worked out automatically; the describe-your-day AI is an optional shortcut.' },
  { at: '2026-10-07T19:17:00+01:00', title: 'Subcontractor calendar readable on busy days and phones', detail: 'Company work shown as one quiet count per day, with a dot grid on phones.' },
  { at: '2026-10-07T19:06:00+01:00', title: 'Fix: subcontractors locked out of their portal', detail: 'Database function repair so subcontractors can sign in again.' },
  { at: '2026-10-07T19:01:00+01:00', title: 'Subcontractor portal error screens', detail: 'They show which email you are signed in as, with a Sign out button.' },
  { at: '2026-10-07T18:49:00+01:00', title: 'Repair: subcontractors with a client-type login', detail: 'Fixes "Account not linked" and heals it on sign-in.' },
  { at: '2026-10-07T16:16:00+01:00', title: 'Subcontractor Calendar tab', detail: 'Their booked days in green plus the company\'s other jobs in grey, with a per-subcontractor switch.' },
  { at: '2026-10-07T15:57:00+01:00', title: 'Calendar month view shows every task', detail: 'Each week grows to fit instead of hiding extras behind "+N more".' },
  { at: '2026-10-07T14:47:00+01:00', title: 'Subcontractor invites go to the subcontractor portal', detail: 'Invite, app, SMS and WhatsApp links no longer use the client portal ones.' },
]
